using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static class ServiceSignBacks {
  const string Group="Presentation | rear service caption",Logs="Logs/ServiceSignBacks",Request="Logs/ServiceSignBacks.request";
  static int checks;
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static void Check(bool ok,string message){checks++;if(!ok)throw new InvalidOperationException("Service sign backs: "+message);}
  static string Pose(Transform t)=>t.localToWorldMatrix.ToString("R");
  static string FrontCaptions(CatalogPlacement p)=>string.Join("|",p.GetComponentsInChildren<TextMesh>(true).Where(t=>!p.transform.Find(Group)||!t.transform.IsChildOf(p.transform.Find(Group))).Select(t=>t.text+Pose(t.transform)));
  [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Run();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  public static void Apply(Scene scene){foreach(string id in new[]{"pinefall-sign-10","pinefall-sign-07"}){var p=All<CatalogPlacement>(scene).Single(x=>x.placementId==id);if(p.transform.Find(Group)&&p.transform.Find(Group).GetComponentInChildren<TextMesh>())continue;if(p.transform.Find(Group))Undo.DestroyObjectImmediate(p.transform.Find(Group).gameObject);var face=p.GetComponentsInChildren<AssetAnchor>(true).Single(a=>a.id=="label-face").transform;var group=new GameObject(Group);group.transform.SetParent(p.transform,false);Undo.RegisterCreatedObjectUndo(group,"Write service sign rear caption");bool depot=id=="pinefall-sign-07";float height=depot?2.09f:2.15f;
   if(depot){var panel=GameObject.CreatePrimitive(PrimitiveType.Cube);panel.name="Blue rear caption panel | clears centre post";UnityEngine.Object.DestroyImmediate(panel.GetComponent<BoxCollider>());panel.transform.SetParent(group.transform,false);panel.transform.SetPositionAndRotation(p.transform.position+face.up*height+face.forward*.236f,face.rotation);panel.transform.localScale=new Vector3(2.2f,.4f,.026f);string path="Assets/Snowglow/Catalog/SceneData/DepotRearCaptionPanel.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!mesh){mesh=UnityEngine.Object.Instantiate(panel.GetComponent<MeshFilter>().sharedMesh);mesh.name="Blue rear caption panel | primitive cube";mesh.uv=Enumerable.Repeat(new Vector2(8.5f/16,.5f),mesh.vertexCount).ToArray();AssetDatabase.CreateAsset(mesh,path);}panel.GetComponent<MeshFilter>().sharedMesh=mesh;var r=panel.GetComponent<MeshRenderer>();r.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Snowglow/Catalog/Sources/AlpineSignBoards/SignPalette.mat");r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;}
   var text=new GameObject("Label | rear "+(depot?"snow depot":"fuel and repair")).AddComponent<TextMesh>();text.transform.SetParent(group.transform,false);text.transform.SetPositionAndRotation(p.transform.position+face.up*height+face.forward*(depot?.256f:.103f),face.rotation*Quaternion.Euler(0,180,0));text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.text=depot?"SNOW DEPOT":"FUEL + REPAIR";text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.fontSize=48;text.characterSize=.13f;text.color=new Color(.96f,.96f,.87f);text.font.RequestCharactersInTexture(text.text,48);var b=text.GetComponent<MeshRenderer>().localBounds;Check(b.size.x>0&&b.size.y>0,"empty glyphs");text.transform.localScale=Vector3.one*Mathf.Min(1,Mathf.Min(2.0f/b.size.x,.22f/b.size.y));}
   var fuel=All<CatalogPlacement>(scene).Single(p=>p.placementId=="pinefall-sign-10");var fuelRear=fuel.transform.Find(Group).GetComponentInChildren<TextMesh>();var fuelFront=fuel.GetComponentsInChildren<TextMesh>().Single(t=>t!=fuelRear&&t.text=="FUEL + REPAIR");var fuelFace=fuel.GetComponentsInChildren<AssetAnchor>().Single(a=>a.id=="label-face").transform;Undo.RecordObjects(new UnityEngine.Object[]{fuelRear,fuelRear.transform},"Match rear fuel caption to front");fuelRear.font=fuelFront.font;fuelRear.fontSize=fuelFront.fontSize;fuelRear.fontStyle=fuelFront.fontStyle;fuelRear.characterSize=fuelFront.characterSize;fuelRear.color=fuelFront.color;fuelRear.transform.localScale=fuelFront.transform.localScale;fuelRear.transform.position=fuelFront.transform.position+fuelFace.forward*(.103f-Vector3.Dot(fuelFront.transform.position-fuel.transform.position,fuelFace.forward));EditorUtility.SetDirty(fuelRear);EditorUtility.SetDirty(fuelRear.transform);
   SignLabelDepthAuthoring.Apply(scene);
  }
  [MenuItem("Snowglow/Environment/Add rear fuel and depot captions")]
  public static void Run(){checks=0;Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");Directory.CreateDirectory(Logs);var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath,"open Pinefall");SceneValidation.Validate(scene);Check(EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before-"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity",true),"backup");var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,p=>Pose(p.transform));var fleet=All<MachineController>(scene).ToDictionary(m=>m.name,m=>Pose(m.transform));var snow=All<SnowField>(scene).Single();string seed=AssetDatabase.GetAssetPath(snow.seed);var hash=AssetDatabase.GetAssetDependencyHash(seed);var fronts=All<CatalogPlacement>(scene).Where(p=>p.placementId=="pinefall-sign-07"||p.placementId=="pinefall-sign-10").ToDictionary(p=>p.placementId,FrontCaptions);
   Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();bool saved=false;try{Apply(scene);foreach(var p in All<CatalogPlacement>(scene).Where(p=>fronts.ContainsKey(p.placementId??"")))Check(fronts[p.placementId]==FrontCaptions(p),"front captions changed");Validate(scene);SceneValidation.Validate(scene);MechanicsChecks.Run();foreach(var p in All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==Pose(p.transform),"placement moved "+p.placementId);foreach(var m in All<MachineController>(scene))Check(fleet[m.name]==Pose(m.transform),"fleet moved");Check(hash==AssetDatabase.GetAssetDependencyHash(seed),"snow changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"save");saved=true;Undo.CollapseUndoOperations(undo);scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);Validate(scene);SceneValidation.Validate(scene);MechanicsChecks.Run();foreach(var p in All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==Pose(p.transform),"reopened placement moved");Check(hash==AssetDatabase.GetAssetDependencyHash(seed),"reopened snow changed");File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+"; "+checks+" checks. Saved/reopened Pinefall, scene validation and 19 snow checks passed. FUEL + REPAIR and SNOW DEPOT now have authored readable rear captions, depth-tested and front-face culled. Depot's small blue rear panel clears its centre support: one 12-triangle cube, existing shared palette, no colliders/lights. Current manually saved catalog/fleet poses and snow seed preserved. Rear-caption pixel checks confirm rear visibility and zero front leakage; native front/back images written. No district rebake or player-save writes. Live driving, touch readability, Android packaging and A07 profiling remain untested.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));}catch{if(!saved)Undo.RevertAllDownToGroup(undo);throw;}
  }
  static int Diff(Color32[] a,Color32[] b)=>a.Zip(b,(x,y)=>Math.Abs(x.r-y.r)+Math.Abs(x.g-y.g)+Math.Abs(x.b-y.b)>20?1:0).Sum();
  static void Validate(Scene scene){foreach(string id in new[]{"pinefall-sign-10","pinefall-sign-07"}){var p=All<CatalogPlacement>(scene).Single(x=>x.placementId==id);var group=p.transform.Find(Group);Check(group&&group.GetComponentsInChildren<TextMesh>().Length==1,"missing rear text "+id);Check(group.GetComponentsInChildren<Collider>().Length==0&&group.GetComponentsInChildren<Light>().Length==0,"rear collision/light");var text=group.GetComponentInChildren<TextMesh>();Check(text.text==(id=="pinefall-sign-10"?"FUEL + REPAIR":"SNOW DEPOT"),"wording");Check(text.GetComponent<WorldSignLabel>()&&text.GetComponent<MeshRenderer>().sharedMaterial.shader.name=="Snowglow/World Sign Text","text binding");
    var preview=new PreviewRenderUtility();try{var copy=UnityEngine.Object.Instantiate(p.gameObject);copy.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);preview.AddSingleGO(copy);foreach(var label in copy.GetComponentsInChildren<WorldSignLabel>())label.Refresh();var rear=copy.transform.Find(Group).GetComponentInChildren<TextMesh>().GetComponent<MeshRenderer>();var face=copy.GetComponentsInChildren<AssetAnchor>().Single(a=>a.id=="label-face").transform;var bounds=CatalogValidation.BoundsOf(copy);var center=bounds.center;preview.camera.orthographic=true;preview.camera.orthographicSize=bounds.extents.y*1.15f;preview.camera.aspect=4f/3;preview.camera.nearClipPlane=.03f;preview.camera.farClipPlane=100;preview.camera.clearFlags=CameraClearFlags.SolidColor;preview.camera.backgroundColor=new Color(.24f,.35f,.4f);preview.ambientColor=new Color(.6f,.6f,.6f);preview.lights[0].intensity=1.1f;foreach(int side in new[]{-1,1}){preview.camera.transform.position=center+face.forward*side*12;preview.camera.transform.LookAt(center);preview.lights[0].transform.rotation=preview.camera.transform.rotation;rear.enabled=true;preview.BeginStaticPreview(new Rect(0,0,960,720));preview.Render(true);var on=preview.EndStaticPreview();File.WriteAllBytes(Logs+"/"+id+(side==1?"-back":"-front")+".png",on.EncodeToPNG());rear.enabled=false;preview.BeginStaticPreview(new Rect(0,0,960,720));preview.Render(true);var off=preview.EndStaticPreview();int pixels=Diff(on.GetPixels32(),off.GetPixels32());Check(side==1?pixels>100:pixels==0,"rear caption visibility "+id+" side "+side+" pixels "+pixels);UnityEngine.Object.DestroyImmediate(on);UnityEngine.Object.DestroyImmediate(off);}}finally{preview.Cleanup();}
   }}
 }
}
